package com.aviatortrends.analyzer;
import java.util.*;
public final class Stats {public static String summary(List<Result> r){if(r.isEmpty())return "No observations yet. Add results or start monitoring.";List<Double>a=new ArrayList<>();double sum=0,min=Double.MAX_VALUE,max=0;int low=0,mid=0;for(Result x:r){double v=x.multiplier;a.add(v);sum+=v;min=Math.min(min,v);max=Math.max(max,v);if(v<2)low++;else if(v<5)mid++;}Collections.sort(a);double med=a.size()%2==1?a.get(a.size()/2):(a.get(a.size()/2-1)+a.get(a.size()/2))/2;int high=a.size()-low-mid;return String.format(Locale.US,"Observations: %d\nMean: %.2fx   Median: %.2fx\nMin: %.2fx   Max: %.2fx\n<2x: %d (%.1f%%)\n2–4.99x: %d (%.1f%%)\n≥5x: %d (%.1f%%)\n\nHistorical analysis only — previous multipliers do not predict the next result.",a.size(),sum/a.size(),med,min,max,low,100d*low/a.size(),mid,100d*mid/a.size(),high,100d*high/a.size());}}
